SELECT AVG(o_count) FROM (
  SELECT a.molecule_id, SUM(a.element = 'o') AS o_count
  FROM atom AS a
  WHERE a.molecule_id IN (
    SELECT b.molecule_id
    FROM bond AS b
    WHERE b.bond_type = '-'
  )
  GROUP BY a.molecule_id
);

